{
  "name": "Students",
  "tests": [
    {
      "name": "Current query",
      "expected": [
        {
          "columns": [
            "name",
            "score"
          ],
          "values": [
            [
              "Ada",
              90
            ],
            [
              "Bob",
              80
            ],
            [
              "Cara",
              null
            ]
          ]
        }
      ]
    },
    {
      "name": "Unordered rows with duplicates",
      "query": "SELECT score FROM students UNION ALL SELECT 90;",
      "ordered": false,
      "expected": [
        {
          "columns": [
            "score"
          ],
          "values": [
            [
              null
            ],
            [
              90
            ],
            [
              80
            ],
            [
              90
            ]
          ]
        }
      ]
    },
    {
      "name": "Empty selection",
      "query": "SELECT name FROM students WHERE 0;",
      "expected": [
        {
          "columns": [
            "name"
          ],
          "values": []
        }
      ]
    },
    {
      "name": "Semicolons in strings",
      "query": "SELECT 'a;b' AS text; SELECT 1 AS n;",
      "expected": [
        {
          "columns": [
            "text"
          ],
          "values": [
            [
              "a;b"
            ]
          ]
        },
        {
          "columns": [
            "n"
          ],
          "values": [
            [
              1
            ]
          ]
        }
      ]
    },
    {
      "name": "Delete inside a test",
      "query": "DELETE FROM students; SELECT count(*) AS total FROM students;",
      "expected": [
        {
          "columns": [
            "total"
          ],
          "values": [
            [
              0
            ]
          ]
        }
      ]
    },
    {
      "name": "Next test starts fresh",
      "query": "SELECT count(*) AS total FROM students;",
      "expected": [
        {
          "columns": [
            "total"
          ],
          "values": [
            [
              3
            ]
          ]
        }
      ]
    },
    {
      "name": "Companion query and types",
      "src": "/details.sql",
      "expected": [
        {
          "columns": [
            "number",
            "text",
            "missing",
            "bytes"
          ],
          "values": [
            [
              1,
              "1",
              null,
              [
                0,
                255
              ]
            ]
          ]
        }
      ]
    },
    {
      "name": "Expected SQL error",
      "query": "SELECT * FROM unknown_table;",
      "error": "no such table: unknown_table"
    },
    {
      "name": "Work in progress",
      "skip": "Add a test for the average score"
    }
  ]
}
